-- Stage 9 — Persistent Progress & Cloud Passport v13
-- Cloud stores bounded learning state only. No raw child answers, prompts, conversations, email, phone, exact DOB or free-text transcript fields.
create type public.evidence_state as enum ('not_yet','supported','independent');
create table public.child_learning_state (child_profile_id uuid primary key references public.child_profiles(id) on delete cascade,curriculum_version text not null default 'foundation-v3',selected_companion text check (selected_companion in ('hamdan','hessa','none')),active_mission_id text,revision bigint not null default 0,updated_at timestamptz not null default now());
create table public.mission_progress (child_profile_id uuid not null references public.child_profiles(id) on delete cascade,mission_id text not null,completed boolean not null default false,evidence public.evidence_state not null default 'not_yet',completed_at timestamptz,updated_at timestamptz not null default now(),primary key(child_profile_id,mission_id));
create table public.passport_evidence (child_profile_id uuid not null references public.child_profiles(id) on delete cascade,passport text not null check(passport in ('safety','skills')),evidence_key text not null,state public.evidence_state not null default 'not_yet',source_mission_id text,updated_at timestamptz not null default now(),primary key(child_profile_id,passport,evidence_key));
create table public.child_achievements (child_profile_id uuid not null references public.child_profiles(id) on delete cascade,achievement_type text not null check(achievement_type in ('trace','badge')),achievement_key text not null,earned_at timestamptz not null default now(),primary key(child_profile_id,achievement_type,achievement_key));
alter table public.child_learning_state enable row level security; alter table public.mission_progress enable row level security; alter table public.passport_evidence enable row level security; alter table public.child_achievements enable row level security;
create policy learning_state_authorized_select on public.child_learning_state for select to authenticated using(exists(select 1 from public.adult_child_authorizations a where a.child_profile_id=child_learning_state.child_profile_id and a.adult_user_id=(select auth.uid())));
create policy mission_progress_authorized_select on public.mission_progress for select to authenticated using(exists(select 1 from public.adult_child_authorizations a where a.child_profile_id=mission_progress.child_profile_id and a.adult_user_id=(select auth.uid())));
create policy passport_evidence_authorized_select on public.passport_evidence for select to authenticated using(exists(select 1 from public.adult_child_authorizations a where a.child_profile_id=passport_evidence.child_profile_id and a.adult_user_id=(select auth.uid())));
create policy achievements_authorized_select on public.child_achievements for select to authenticated using(exists(select 1 from public.adult_child_authorizations a where a.child_profile_id=child_achievements.child_profile_id and a.adult_user_id=(select auth.uid())));
create or replace function public.sync_child_learning_state(p_child_profile_id uuid,p_payload jsonb,p_expected_revision bigint default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_uid uuid:=auth.uid(); v_revision bigint; v_item jsonb; begin if v_uid is null then raise exception 'authentication_required'; end if; if not exists(select 1 from public.adult_child_authorizations where adult_user_id=v_uid and child_profile_id=p_child_profile_id) then raise exception 'not_authorized'; end if; if exists(select 1 from public.child_profiles where id=p_child_profile_id and archived_at is not null) then raise exception 'profile_archived'; end if; insert into public.child_learning_state(child_profile_id) values(p_child_profile_id) on conflict do nothing; select revision into v_revision from public.child_learning_state where child_profile_id=p_child_profile_id for update; if p_expected_revision is not null and p_expected_revision<>v_revision then return jsonb_build_object('ok',false,'conflict',true,'revision',v_revision); end if; update public.child_learning_state set curriculum_version=coalesce(nullif(p_payload->>'curriculum_version',''),curriculum_version),selected_companion=case when p_payload?'selected_companion' then nullif(p_payload->>'selected_companion','') else selected_companion end,active_mission_id=case when p_payload?'active_mission_id' then nullif(p_payload->>'active_mission_id','') else active_mission_id end,revision=revision+1,updated_at=now() where child_profile_id=p_child_profile_id returning revision into v_revision; for v_item in select value from jsonb_array_elements(coalesce(p_payload->'missions','[]'::jsonb)) loop insert into public.mission_progress(child_profile_id,mission_id,completed,evidence,completed_at,updated_at) values(p_child_profile_id,v_item->>'mission_id',coalesce((v_item->>'completed')::boolean,false),coalesce((v_item->>'evidence')::public.evidence_state,'not_yet'),case when coalesce((v_item->>'completed')::boolean,false) then now() else null end,now()) on conflict(child_profile_id,mission_id) do update set completed=mission_progress.completed or excluded.completed,evidence=case when mission_progress.evidence='independent' or excluded.evidence='independent' then 'independent'::public.evidence_state when mission_progress.evidence='supported' or excluded.evidence='supported' then 'supported'::public.evidence_state else 'not_yet'::public.evidence_state end,completed_at=coalesce(mission_progress.completed_at,excluded.completed_at),updated_at=now(); end loop; for v_item in select value from jsonb_array_elements(coalesce(p_payload->'evidence','[]'::jsonb)) loop insert into public.passport_evidence(child_profile_id,passport,evidence_key,state,source_mission_id,updated_at) values(p_child_profile_id,v_item->>'passport',v_item->>'evidence_key',coalesce((v_item->>'state')::public.evidence_state,'not_yet'),nullif(v_item->>'source_mission_id',''),now()) on conflict(child_profile_id,passport,evidence_key) do update set state=case when passport_evidence.state='independent' or excluded.state='independent' then 'independent'::public.evidence_state when passport_evidence.state='supported' or excluded.state='supported' then 'supported'::public.evidence_state else 'not_yet'::public.evidence_state end,source_mission_id=coalesce(passport_evidence.source_mission_id,excluded.source_mission_id),updated_at=now(); end loop; for v_item in select value from jsonb_array_elements(coalesce(p_payload->'achievements','[]'::jsonb)) loop insert into public.child_achievements(child_profile_id,achievement_type,achievement_key) values(p_child_profile_id,v_item->>'type',v_item->>'key') on conflict do nothing; end loop; return jsonb_build_object('ok',true,'conflict',false,'revision',v_revision); end$$;
revoke all on function public.sync_child_learning_state(uuid,jsonb,bigint) from public,anon; grant execute on function public.sync_child_learning_state(uuid,jsonb,bigint) to authenticated;
create or replace function public.get_child_cloud_passport(p_child_profile_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp stable as $$ begin if auth.uid() is null or not exists(select 1 from public.adult_child_authorizations where adult_user_id=auth.uid() and child_profile_id=p_child_profile_id) then raise exception 'not_authorized'; end if; return jsonb_build_object('state',(select to_jsonb(s) from public.child_learning_state s where s.child_profile_id=p_child_profile_id),'missions',coalesce((select jsonb_agg(to_jsonb(m) order by m.mission_id) from public.mission_progress m where m.child_profile_id=p_child_profile_id),'[]'::jsonb),'evidence',coalesce((select jsonb_agg(to_jsonb(e) order by e.passport,e.evidence_key) from public.passport_evidence e where e.child_profile_id=p_child_profile_id),'[]'::jsonb),'achievements',coalesce((select jsonb_agg(to_jsonb(a) order by a.achievement_type,a.achievement_key) from public.child_achievements a where a.child_profile_id=p_child_profile_id),'[]'::jsonb)); end$$;
revoke all on function public.get_child_cloud_passport(uuid) from public,anon; grant execute on function public.get_child_cloud_passport(uuid) to authenticated;